# only //1 ever reached the DB; //2,3,4,5 were rejected before insert
curl localhost:8055/items/type_mismatch_repro -H "Authorization: Bearer $ADMIN_TOKEN"
# 200 OK -> {
#   "data": [
#     {
#       "id": 1,
#       "endvisit_at": null,
